export interface Item {
  readonly type: string;
  readonly material?: string;
  readonly enchantment?: number;
  readonly cursed?: boolean;
}

export interface QuoteStep {
  readonly op: "quote";
  readonly items: readonly Item[];
}

export interface Damage {
  readonly itemType: string;
  readonly amount: number;
}

export interface Incident {
  readonly cause: string;
  readonly damages: readonly Damage[];
}

export interface ClaimStep {
  readonly op: "claim";
  readonly policy: number;
  readonly incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Customer {
  readonly yearsWithMHPCO: number;
}

export interface Scenario {
  readonly customer: Customer;
  readonly steps: readonly Step[];
}

export interface QuoteResult {
  readonly premium: number;
}

export interface ClaimResult {
  readonly payout: number;
  readonly remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  readonly results: readonly StepResult[];
}

export function runScenario(_scenario: Scenario): ScenarioResult {
  return undefined as unknown as ScenarioResult;
}

